import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel for matrix multiplication (one thread per output element)
matmul_kernel_source = """
__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N; // row index
        int j = idx % N; // column index
        float sum = 0.0f;
        for (int l = 0; l < K; ++l) {
            sum += A[i * K + l] * B[l * N + j];
        }
        C[idx] = sum;
    }
}
"""

# CUDA function that launches the kernel
matmul_cuda_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto size = A.numel();
    auto out = torch::zeros_like(A);

    const int block_size = 256;
    // Number of output elements (M*N)
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    int total_outputs = M * N;
    const int num_blocks = (total_outputs + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float()>, out.data_ptr<float()>, M, K, N);

    return out;
}
"""

# C++ source for the function signature
matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile inline CUDA code
matmul = load_inline(
    name="matmul",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul = matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul.matmul_cuda(A, B)
